import{_ as r,o as a,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2018-May-31 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2018-May-31 :: Ceph Performance Weekly","date":"2018-06-01T00:00:00.000Z","updated":"2018-06-02T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","内存管理","锁优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-May-31_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2018/2018-May-31_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),l={name:"posts/2018/2018-May-31_-_-_Ceph_Performance_Weekly.md"};function s(p,e,_,n,i,c){return a(),o("div",null,[...e[0]||(e[0]=[t("<p>本次会议主要讨论了Ceph项目的多个进展，包括Beast项目、Rocky CB1 Mark、内存使用优化、锁优化等方面。</p><p><strong>Beast项目</strong>： Adam Emerson正在将兼容I/O接口集成到Beast中，会议强调需要关注接口兼容性问题，确保与解放应用程序的兼容性。</p><p><strong>Rocky CB1 Mark</strong>： 会议讨论了该PR的视频功能，认为其对性能提升有限，但不会造成负面影响。</p><p><strong>内存使用优化</strong>： 会议讨论了OS memory usage的问题，希望实现内存使用量的动态调整，并根据优先级分配内存。同时探讨了如何获取内存分配的统计数据，并考虑使用malloc_usable_size等接口。</p><p><strong>锁优化</strong>： 会议讨论了scrubbing期间锁的竞争问题，并分析了可能的锁冲突原因。建议使用GDB wall clock profiler或Adams wall clock profiler进行分析，并尝试调整scrubbing步长大小以改善性能。</p><p><strong>后续行动计划</strong>：</p><ul><li>Adam Emerson继续推进Beast项目，并提交相关PR。</li><li>会议参与者积极审查Adam提交的PR。</li><li>会议参与者继续关注内存使用优化工作，并尝试获取相关统计数据。</li><li>会议参与者尝试使用GDB wall clock profiler或Adams wall clock profiler分析scrubbing期间锁的竞争问题。</li><li>会议参与者尝试调整scrubbing步长大小以改善性能。</li></ul><p><strong>其他事项</strong>：</p><ul><li>会议讨论了rocksdb buffer size动态调整的可能性。</li><li>会议鼓励大家积极分享经验和反馈。</li></ul><p>本次会议讨论了Ceph项目的多个进展，并制定了后续行动计划。会议氛围积极，参与者积极参与讨论，为Ceph项目的持续发展贡献力量。</p>",10)])])}const f=r(l,[["render",s]]);export{d as __pageData,f as default};
